// === Tab: mySketch ===
/*
A fork from a sketch by Juan Carlos Ponce Campuzano
  https://www.patreon.com/jcponce
  https://bestiariotopologico.blogspot.com/2024/07/que-son-las-particulas-lenia.html

  Based upon this Tutorial by Alexander Mordvintsev:
  Particle Lenia from scratch
  https://observablehq.com/@znah/particle-lenia-from-scratch 

  Excellent study about automating the search for artificial Life with Foundation Models:
  ""!!!==== https://sakana.ai/asal/ ===!!!""
*/

// --------------------------------------------------------------
// * Lenia is a continuous generalization of cellular automata, such as Conway's Game of Life, where cells have continuous states (not just on/off) and evolve smoothly over time and space. 
// * It uses kernel functions (often Gaussian-like) to compute neighborhood influences and growth rules to update states, leading to emergent patterns resembling biological or physical systems. 
// * This code implements a particle-based variant of Lenia, where discrete points interact via repulsion and attraction forces derived from potential fields, simulating clustering and dynamic behaviors.
// --------------------------------------------------------------

let isMobile = /iPhone|iPod|Android/i.test(navigator.userAgent);
let params = {
	mu_k: 4.0,
	sigma_k: 1.0,
	w_k: 0.022, // Parameters for the kernel (attraction) function: mean (mu_k), std dev (sigma_k), weight (w_k)
	mu_g: 0.6,
	sigma_g: 0.15,
	c_rep: 1.0, // Parameters for growth function (mu_g, sigma_g) and repulsion strength (c_rep)
	dt: 0.1 // Time step for simulation updates
};
let point_n = 200; // Number of particles in the system
let points; // Array storing particle positions (x, y) in interleaved format [x1, y1, x2, y2, ...]
let fields; // Object to hold computed field values and gradients for repulsion (R) and attraction (U)
let steps_per_frame; // Number of simulation steps to run per draw frame (randomized for variability)
let energies; // Store energy values for each particle (used for visualization)
let minEnergy, maxEnergy; // Track min/max energy for color mapping
let scale_factor;

function setup() {
	background(0);
	if (isMobile) {
		createCanvas(360, 360);
		scale_factor = 22.0;
	} else {
		createCanvas(800, 800);
		scale_factor = 35.0;
	}

	describe('A dynamic simulation of particles in a Lenia system,' +
		'clustering and moving based on attraction and repulsion forces, visualized with energy-colored ellipses.')

	points = init(new Float32Array(point_n * 2)); // Initialize particle positions in a typed array for efficiency
	fields = {
		R_val: new Float32Array(point_n), // Repulsion potential values for each particle
		U_val: new Float32Array(point_n), // Attraction (kernel) sum values for each particle (like neighborhood density in Lenia)
		R_grad: new Float32Array(point_n * 2), // Gradients of repulsion (forces) [dx1, dy1, dx2, dy2, ...]
		U_grad: new Float32Array(point_n * 2) // Gradients of attraction [dx1, dy1, dx2, dy2, ...]
	};

	energies = new Float32Array(point_n); // Initialize energy array for particle visualization

	colorMode(HSB, 360, 100, 100, 100); // Use HSB color mode for smooth hue-based coloring
	noStroke(); // Disable outlines for drawn shapes
	steps_per_frame = 12; // steps per frame for dynamic pacing

	// Initialize min/max energy with extreme values for later normalization
	minEnergy = Infinity;
	maxEnergy = -Infinity;
}

function draw() {
	// Run multiple simulation steps per frame to advance the system
	for (let i = 0; i < steps_per_frame; ++i) stepSimulation();

	background(0, 20);
	translate(width / 2, height / 2);
	scale(width / scale_factor); // To fit the simulation space to the canvas

	// Calculate energy range for this frame (for color mapping)
	updateEnergyRange();

	// Render each particle as a circle, sized and colored based on fields and energy
	for (let i = 0; i < point_n; ++i) {
		let x = points[i * 2],
			y = points[i * 2 + 1]; // Get particle position
		let r = params.c_rep / (fields.R_val[i] * 5.0); // Compute radius based on repulsion value (smaller when repulsed)

		// Set color based on energy (low to high: blue to red)
		let hue = mapEnergyToColor(energies[i]);
		fill(hue, 80, 100, 70); // Fill with semi-transparent color

		circle(x, y, r * 2); // The particle
	}

	//if(frameCount % 60 == 0) print(frameRate())
}

function updateEnergyRange() {
	// Update min/max energy values with some exponential smoothing to stabilize visualization
	for (let i = 0; i < point_n; ++i) {
		minEnergy = min(minEnergy * 0.99 + energies[i] * 0.01, energies[i]);
		maxEnergy = max(maxEnergy * 0.99 + energies[i] * 0.01, energies[i]);
	}

	// Ensuring there's always some range to avoid division by zero in mapping
	if (maxEnergy - minEnergy < 0.01) {
		maxEnergy = minEnergy + 0.1;
	}
}

function mapEnergyToColor(energy) {
	// Normalize energy to 0-1 range for color mapping
	let normalizedEnergy = (energy - minEnergy) / (maxEnergy - minEnergy);

	// Clamp to 0-1 to handle outliers
	normalizedEnergy = constrain(normalizedEnergy, 0, 1);

	// Map to hue range (blue to red heatmap style)
	return map(normalizedEnergy, 0, 1, 240, 0);
}

function init(points) {
	// Randomly initialize particle positions within a [-6, 6] square
	for (let i = 0; i < point_n; ++i) {
		points[i * 2] = (Math.random() - 0.5) * 12;
		points[i * 2 + 1] = (Math.random() - 0.5) * 12;
	}
	return points;
}

function add_xy(a, i, x, y, c) {
	// Add scaled vector (x, y)*c to the i-th point in array a
	a[i * 2] += x * c;
	a[i * 2 + 1] += y * c;
}

function compute_fields() {
	const {
		R_val,
		U_val,
		R_grad,
		U_grad
	} = fields;
	const {
		c_rep,
		mu_k,
		sigma_k,
		w_k
	} = params;

	// Initialize fields with self-interaction terms (at r=0)
	R_val.fill(repulsion_f(0.0, c_rep)[0]);
	U_val.fill(peak_f(0.0, mu_k, sigma_k, w_k)[0]);
	R_grad.fill(0);
	U_grad.fill(0);

	// Compute pairwise interactions (O(n^2) loop, core of Lenia-like computation)
	for (let i = 0; i < point_n - 1; ++i) {
		for (let j = i + 1; j < point_n; ++j) {
			let rx = points[i * 2] - points[j * 2]; // Delta x
			let ry = points[i * 2 + 1] - points[j * 2 + 1]; // Delta y
			const r = Math.sqrt(rx * rx + ry * ry) + 1e-20; // Distance (with epsilon to avoid division by zero)
			rx /= r; // Normalize direction
			ry /= r;

			// Repulsion: short-range (only if r < 1), quadratic potential
			if (r < 1.0) {
				const [R, dR] = repulsion_f(r, c_rep); // Potential and derivative
				add_xy(R_grad, i, rx, ry, dR); // Add force to i
				add_xy(R_grad, j, rx, ry, -dR); // Add opposite force to j
				R_val[i] += R; // Accumulate potential
				R_val[j] += R;
			}

			// Attraction/kernel: Gaussian peak at distance mu_k, contributes to "neighborhood" sum U
			const [K, dK] = peak_f(r, mu_k, sigma_k, w_k); // Kernel value and derivative
			add_xy(U_grad, i, rx, ry, dK); // Add gradient to i
			add_xy(U_grad, j, rx, ry, -dK); // Add opposite to j
			U_val[i] += K; // Accumulate kernel sum
			U_val[j] += K;
		}
	}
}

// Repulsion function: quadratic for close distances (soft core potential)
function repulsion_f(x, c_rep) {
	const t = Math.max(1.0 - x, 0.0); // Linear ramp from 1 to 0 as x goes from 0 to 1
	return [0.5 * c_rep * t * t, -c_rep * t]; // Potential (integral) and force (derivative)
}

// Fast approximation of exp(-x) using repeated squaring (for efficiency in Gaussian)
function fast_exp(x) {
	let t = 1.0 + x / 32.0;
	t *= t;
	t *= t;
	t *= t;
	t *= t;
	t *= t;
	return t;
}

// Kernel function: Gaussian bell curve centered at mu, for neighborhood weighting
function peak_f(x, mu, sigma, w = 1.0) {
	const t = (x - mu) / sigma; // Normalized distance
	const y = w / fast_exp(t * t); // Gaussian value (note: 1/exp(t^2) is like exp(-t^2) but inverted scaling)
	return [y, -2.0 * t * y / sigma]; // Value and derivative (for gradient)
}

function stepSimulation() {
	const {
		R_val,
		U_val,
		R_grad,
		U_grad
	} = fields;
	const {
		mu_g,
		sigma_g,
		dt
	} = params;

	// First, compute all fields and gradients
	compute_fields();

	let total_E = 0.0; // Track total energy for potential return (average)

	// For each particle, compute movement based on gradients and growth
	for (let i = 0; i < point_n; ++i) {
		// Growth term: another Gaussian applied to the summed kernel U_val (like Lenia's growth function)
		const [G, dG] = peak_f(U_val[i], mu_g, sigma_g); // Growth value and derivative

		// Velocity: growth-modulated attraction gradient minus repulsion gradient
		const vx = dG * U_grad[i * 2] - R_grad[i * 2];
		const vy = dG * U_grad[i * 2 + 1] - R_grad[i * 2 + 1];

		// Update position: Euler integration
		add_xy(points, i, vx, vy, dt);

		// Store energy: repulsion potential minus growth (for visualization)
		energies[i] = R_val[i] - G;
		total_E += energies[i];
	}
}

// Handler to randomize parameters on mouse click, resetting the simulation feel
function mousePressed() {
	params.mu_k = random(1.0, 5.0);
	params.sigma_k = random(0.1, 2.0);
	params.w_k = random(0.01, 0.07);
	params.mu_g = random(0.1, 1.0);
	params.sigma_g = random(0.05, 0.3);
	params.c_rep = random(0.1, 2.0);

	// Reset energy range when parameters change
	minEnergy = Infinity;
	maxEnergy = -Infinity;
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
